// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address target, bytes calldata data) public {
        vm.assume(amount > 0);
        vm.assume(target != address(c));
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        vm.startPrank(c.owner());
        c.sendMoney(target, amount, data);
        vm.stopPrank();
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore - amount);
    }
}
